        savingRatio > 0
          ? `Cutting ${(savingRatio * 100).toFixed(0)}% of original interest`
          : 'No pre-payments made yet',
    },
    {
      label: 'Effective Cost',
      score: Math.round(costScore),
      max: W_COST,
      hint: `You repay ${costMultiple.toFixed(2)}x the borrowed amount`,
    },
    {
      label: 'Tenure',
