    {
      label: 'Progress',
      value: `${progressPct}%`,
      sub: `${monthsCompleted} of ${wp.totalMonths} months`,
      tooltip: 'How much of your loan principal you have repaid so far based on the current date.',
      icon: <TrendingUp className="h-5 w-5" strokeWidth={1.5} />,
