3	import { useState, useRef, useEffect } from 'react';
4	import { MessageCircle, X, Trash2, Send, Bot } from 'lucide-react';
5	import { useChat } from '../hooks/useChat';
6	import type { LoanInput, PrePayment, RateChange } from '../types/loan';
7	
8	interface Props {
9	  loan: LoanInput;
10	  prePayments: PrePayment[];
11	  rateChanges: RateChange[];
12	}
13	
14	const SUGGESTIONS = [
15	  'When will my loan close?',
16	  'How much interest am I saving?',
17	  'What if I prepay 5 lakhs?',
18	  'Summarize my loan',
19	];
20	
21	export const ChatWidget = ({ loan, prePayments, rateChanges }: Props) => {
22	  const [isOpen, setIsOpen] = useState(false);
23	  const [input, setInput] = useState('');
24	  const messagesEndRef = useRef<HTMLDivElement>(null);
25	  const inputRef = useRef<HTMLInputElement>(null);
26	
27	  const { messages, isLoading, sendMessage, clearMessages } = useChat({
28	    loan,
29	    prePayments,
30	    rateChanges,
31	  });
32	
33	  useEffect(() => {
34	    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
35	  }, [messages]);
36	
37	  useEffect(() => {
38	    if (isOpen) setTimeout(() => inputRef.current?.focus(), 100);
39	  }, [isOpen]);
40	
41	  const handleSend = () => {
42	    const text = input.trim();
43	    if (!text || isLoading) return;
44	    setInput('');
45	    sendMessage(text);
46	  };
47	
48	  const handleKeyDown = (e: React.KeyboardEvent) => {
49	    if (e.key === 'Enter' && !e.shiftKey) {
50	      e.preventDefault();
51	      handleSend();
52	    }
53	  };
54	
55	  return (
56	    <>
57	      {/* Floating Button */}
58	      <button
59	        onClick={() => setIsOpen(!isOpen)}
60	        className={`cursor-pointer fixed bottom-5 right-5 z-50 flex items-center justify-center rounded-full shadow-lg transition-all duration-300 hover:shadow-xl hover:scale-105 active:scale-95 ${
61	          isOpen
62	            ? 'h-12 w-12 bg-slate-700 text-white shadow-slate-700/25 hover:shadow-slate-700/35 sm:h-14 sm:w-14'
63	            : 'h-14 w-14 bg-gradient-to-br from-blue-600 to-indigo-600 text-white shadow-blue-600/30 hover:shadow-blue-600/40'
64	        }`}
65	        aria-label={isOpen ? 'Close chat' : 'Open chat'}
66	      >
67	        {isOpen ? (
68	          <X className="h-5 w-5 sm:h-6 sm:w-6" strokeWidth={2} />
69	        ) : (
70	          <MessageCircle className="h-6 w-6" strokeWidth={2} />
71	        )}
72	      </button>
73	
74	      {/* Chat Panel */}
75	      {isOpen && (
76	        <div
77	          className={`fixed z-50 flex flex-col bg-white shadow-2xl transition-all duration-300
78	            max-sm:inset-0
79	            sm:bottom-24 sm:right-5 sm:rounded-2xl sm:border sm:border-slate-200`}
80	          style={{
81	            width: undefined,
82	            height: undefined,
83	          }}
84	        >
85	          {/* Mobile: full-screen sizing via inset-0 + Tailwind classes */}
