97	            <div className="flex items-center justify-between border-b border-slate-200 px-4 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 sm:bg-none sm:bg-white">
98	              <div className="flex items-center gap-2.5">
99	                <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-white/20 sm:bg-gradient-to-br sm:from-blue-600 sm:to-indigo-600">
100	                  <Bot className="h-4 w-4 text-white" />
101	                </div>
102	                <div>
