import { useMemo } from 'react';
import { RadialBarChart, RadialBar, PolarAngleAxis, ResponsiveContainer } from 'recharts';
import { HeartPulse, Lightbulb } from 'lucide-react';
import type { LoanInput, LoanSummary } from '../types/loan';
import { computeHealthScore, type HealthGrade } from '../utils/insights';
import { InfoTooltip } from './InfoTooltip';

interface Props {
  loan: LoanInput;
  summary: LoanSummary;
}

const GRADE_COLOR: Record<HealthGrade, string> = {
  Excellent: '#059669', // emerald-600
  Good: '#2563eb', // blue-600
  Fair: '#d97706', // amber-600
  'Needs Attention': '#dc2626', // red-600
};

export const HealthScore = ({ loan, summary }: Props) => {
  const health = useMemo(() => computeHealthScore(loan, summary), [loan, summary]);
  const color = GRADE_COLOR[health.grade];

  return (
    <div className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6 shadow-sm">
      <div className="mb-4 flex items-center gap-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-rose-50 text-rose-600">
          <HeartPulse className="h-5 w-5" />
        </div>
        <h2 className="flex items-center gap-1.5 text-base font-bold text-slate-900">
          Loan Health Score
          <InfoTooltip text="A 0–100 score based on your interest rate vs market, pre-payment activity, total cost, and tenure. Higher is better." />
        </h2>
      </div>

      <div className="flex flex-col items-center gap-5 sm:flex-row sm:items-center sm:gap-6">
        <div className="relative h-40 w-40 shrink-0">
          <ResponsiveContainer width="100%" height="100%">
            <RadialBarChart
              innerRadius="72%"
              outerRadius="100%"
              data={[{ value: health.score, fill: color }]}
              startAngle={90}
              endAngle={-270}
            >
              <PolarAngleAxis type="number" domain={[0, 100]} tick={false} />
              <RadialBar background={{ fill: '#f1f5f9' }} dataKey="value" cornerRadius={12} />
            </RadialBarChart>
          </ResponsiveContainer>
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-4xl font-bold tracking-tight" style={{ color }}>
              {health.score}
            </span>
            <span className="text-xs font-semibold uppercase tracking-wider" style={{ color }}>
              {health.grade}
            </span>
          </div>
        </div>

        <div className="w-full space-y-2.5">
          {health.factors.map((f) => {
            const pct = (f.score / f.max) * 100;
            return (
              <div key={f.label}>
                <div className="flex items-center justify-between text-xs">
                  <span className="font-medium text-slate-600" title={f.hint}>
                    {f.label}
                  </span>
                  <span className="tabular-nums text-slate-400">
                    {f.score}/{f.max}
                  </span>
                </div>
                <div className="mt-1 h-1.5 w-full overflow-hidden rounded-full bg-slate-100">
                  <div
                    className="h-full rounded-full transition-all duration-700"
                    style={{ width: `${pct}%`, backgroundColor: color }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="mt-5 space-y-2 border-t border-slate-100 pt-4">
        {health.tips.map((tip, i) => (
          <div key={i} className="flex items-start gap-2 text-xs text-slate-600">
            <Lightbulb className="mt-0.5 h-3.5 w-3.5 shrink-0 text-amber-500" />
            <span>{tip}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

import { useMemo } from 'react';
import { TrendingUp, ArrowUpRight } from 'lucide-react';
import type { LoanInput, PrePayment, RateChange, AmortizationResult } from '../types/loan';
import { formatCurrency } from '../utils/formatters';
import { computeRateSensitivity } from '../utils/insights';
import { InfoTooltip } from './InfoTooltip';

interface Props {
  loan: LoanInput;
  prePayments: PrePayment[];
  rateChanges: RateChange[];
  baseline: AmortizationResult;
}

export const RateSensitivity = ({ loan, prePayments, rateChanges, baseline }: Props) => {
  const rows = useMemo(
    () => computeRateSensitivity(loan, prePayments, rateChanges, baseline),
    [loan, prePayments, rateChanges, baseline],
  );

  return (
    <div className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6 shadow-sm">
      <div className="mb-1 flex items-center gap-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-orange-50 text-orange-600">
          <TrendingUp className="h-5 w-5" />
        </div>
        <h2 className="flex items-center gap-1.5 text-base font-bold text-slate-900">
          Rate Sensitivity
          <InfoTooltip text="How much more you would pay in interest and how many extra months it would add if your interest rate rose across the board." />
        </h2>
      </div>
      <p className="mb-4 text-xs text-slate-500">
        If your rate rose from {loan.annualRate}%, here&apos;s the extra cost.
      </p>

      <div className="space-y-3">
        {rows.map((row) => (
          <div
            key={row.delta}
            className="flex items-center justify-between rounded-xl border border-slate-100 bg-slate-50/60 px-4 py-3"
          >
            <div className="flex items-center gap-2">
              <span className="flex items-center gap-1 rounded-lg bg-orange-100 px-2 py-1 text-xs font-bold text-orange-700">
                <ArrowUpRight className="h-3.5 w-3.5" />+{row.delta}%
              </span>
              <span className="text-xs text-slate-500">→ {row.newRate}%</span>
            </div>
            <div className="flex items-center gap-4 text-right">
              <div>
                <p className="text-sm font-bold tabular-nums text-rose-600">
                  +{formatCurrency(row.extraInterest)}
                </p>
                <p className="text-[10px] uppercase tracking-wider text-slate-400">interest</p>
              </div>
              <div>
                <p className="text-sm font-bold tabular-nums text-slate-700">+{row.extraMonths}</p>
                <p className="text-[10px] uppercase tracking-wider text-slate-400">months</p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import { useMemo } from 'react';
import { Scale, CalendarClock, CalendarDays, PieChart } from 'lucide-react';
import type { AmortizationResult } from '../types/loan';
import { formatCurrency, formatDate } from '../utils/formatters';
import { computeKeyInsights } from '../utils/insights';
import { InfoTooltip } from './InfoTooltip';

interface Props {
  result: AmortizationResult;
}

export const InsightStrip = ({ result }: Props) => {
  const insights = useMemo(() => computeKeyInsights(result), [result]);

  const items = [
    {
      icon: <Scale className="h-4 w-4" />,
      iconBg: 'bg-violet-100 text-violet-600',
      label: 'Break-even Month',
      value:
        insights.breakevenMonth !== null
          ? `#${insights.breakevenMonth}`
          : '—',
      sub:
        insights.breakevenDate !== null
          ? formatDate(insights.breakevenDate)
          : 'Interest stays higher',
      tooltip:
        'The first EMI where you pay more towards principal than interest — the turning point of your loan.',
    },
    {
      icon: <CalendarClock className="h-4 w-4" />,
      iconBg: 'bg-rose-100 text-rose-600',
      label: 'Avg Monthly Interest',
      value: formatCurrency(insights.avgMonthlyInterest),
      sub: 'across full tenure',
      tooltip: 'Your total interest spread evenly across every month of the loan.',
    },
    {
      icon: <CalendarDays className="h-4 w-4" />,
      iconBg: 'bg-amber-100 text-amber-600',
      label: 'Interest / Day',
      value: formatCurrency(insights.interestPerDay),
      sub: 'average daily cost',
      tooltip: 'On average, this is what your loan costs you in interest every single day.',
    },
    {
      icon: <PieChart className="h-4 w-4" />,
      iconBg: 'bg-cyan-100 text-cyan-600',
      label: 'Interest Share',
      value: `${insights.interestSharePct.toFixed(1)}%`,
      sub: 'of total amount paid',
      tooltip: 'What portion of everything you pay to the bank is interest rather than principal.',
    },
  ];

  return (
    <div className="grid grid-cols-2 gap-3 sm:gap-4 lg:grid-cols-4">
      {items.map((item) => (
        <div
          key={item.label}
          className="rounded-xl sm:rounded-2xl border border-slate-200 bg-white p-3 sm:p-4 shadow-sm"
        >
          <div className="mb-2 flex items-center justify-between">
            <span className="flex items-center gap-1 text-[10px] sm:text-xs font-semibold uppercase tracking-wider text-slate-500">
              {item.label}
              <InfoTooltip text={item.tooltip} />
            </span>
            <div
              className={`flex h-6 w-6 sm:h-7 sm:w-7 items-center justify-center rounded-md sm:rounded-lg ${item.iconBg}`}
            >
              {item.icon}
            </div>
          </div>
          <p className="text-base sm:text-xl font-bold tracking-tight text-slate-900">
            {item.value}
          </p>
          <p className="mt-0.5 truncate text-[10px] sm:text-xs text-slate-400">{item.sub}</p>
        </div>
      ))}
    </div>
  );
};

