          <div className="mb-2 flex items-center justify-between">
            <span className="flex items-center gap-1 text-[10px] sm:text-xs font-semibold uppercase tracking-wider text-slate-500">
              {item.label}
              <InfoTooltip text={item.tooltip} />
            </span>
            <div
              className={`flex h-6 w-6 sm:h-7 sm:w-7 items-center justify-center rounded-md sm:rounded-lg ${item.iconBg}`}
            >
              {item.icon}
            </div>
          </div>
          <p className="text-base sm:text-xl font-bold tracking-tight text-slate-900">
            {item.value}
          </p>
          <p className="mt-0.5 truncate text-[10px] sm:text-xs text-slate-400">{item.sub}</p>
        </div>
      ))}
    </div>
  );
};
